def flatten_nested(items):
    """Return a flat list of integers from an arbitrarily nested list."""
    result = []

    def _flatten(lst):
        for elem in lst:
            if isinstance(elem, int):
                result.append(elem)
            else:
                _flatten(elem)

    _flatten(items)
    return result

